-- Perfume Sales & Customer Analysis-- Query 1: Calculate total revenueSELECT    SUM(Revenue) AS Total_RevenueFROM PerfumeImport;-- Query 2: Calculate total cost and total profitSELECT    SUM(total_cost) AS Total_Cost,    SUM(profit) AS Total_ProfitFROM PerfumeImport;-- Query 3: Total profit by perfumeSELECT    product_name,    SUM(profit) AS Total_ProfitFROM PerfumeImportGROUP BY product_nameORDER BY Total_Profit DESC;-- Query 4: Revenue by sales channelSELECT    sales_channel,    SUM(revenue) AS Total_RevenueFROM PerfumeImportGROUP BY sales_channelORDER BY Total_Revenue DESC;-- Query 5: Revenue by customer typeSELECT    customer_type,    SUM(revenue) AS Total_RevenueFROM PerfumeImportGROUP BY customer_typeORDER BY Total_Revenue DESC;-- Query 6: Return rate by sales channelSELECT    sales_channel,    COUNT(*) AS Total_Orders,    SUM(CASE        WHEN LOWER(TRIM(returned)) = 'yes' THEN 1        ELSE 0    END) AS Returned_Orders,    ROUND(        100.0 * SUM(CASE            WHEN LOWER(TRIM(returned)) = 'yes' THEN 1            ELSE 0        END) / COUNT(*),        2    ) AS Return_Rate_PercentFROM PerfumeImportGROUP BY sales_channelORDER BY Return_Rate_Percent DESC;-- Query 7: Average rating by perfumeSELECT    product_name,    ROUND(AVG(rating), 2) AS Average_RatingFROM PerfumeImportGROUP BY product_nameORDER BY Average_Rating DESC;-- Query 8: Total profit by customer locationSELECT    location,    SUM(profit) AS Total_ProfitFROM PerfumeImportGROUP BY locationORDER BY Total_Profit DESC;-- Query 9: Revenue and profit by genderSELECT    gender,    SUM(revenue) AS Total_Revenue,    SUM(profit) AS Total_ProfitFROM PerfumeImportGROUP BY genderORDER BY Total_Revenue DESC;-- Query 10: Revenue by payment methodSELECT    payment_method,    COUNT(*) AS Total_Sales,    SUM(revenue) AS Total_RevenueFROM PerfumeImportGROUP BY payment_methodORDER BY Total_Revenue DESC;-- Query 11: Monthly revenue analysisSELECT    strftime('%Y-%m', order_date) AS Sales_Month,    SUM(revenue) AS Total_Revenue,    SUM(profit) AS Total_ProfitFROM PerfumeImportGROUP BY strftime('%Y-%m', order_date)ORDER BY Sales_Month ASC;